"""Securi secret resolution via Azure Key Vault (generated by the Securi wizard).

All runtime secrets (JWT signing key, Cosmos key) resolve through
DefaultAzureCredential: local dev uses your Azure CLI login, CI uses a
managed identity. Nothing plaintext ever lands in git.
"""
import os


def get_secret(name: str) -> str:
    """Resolve a secret from Key Vault; fall back to env vars in dev."""
    vault_url = os.environ.get("SECURI_KEYVAULT_URL")
    if not vault_url:
        env_name = name.upper().replace("-", "_")
        value = os.environ.get(env_name) or os.environ.get(f"SECURI_DEV_{env_name}")
        if value:
            return value
        raise RuntimeError(f"Set SECURI_KEYVAULT_URL or {env_name}")
    from azure.identity import DefaultAzureCredential
    from azure.keyvault.secrets import SecretClient

    client = SecretClient(vault_url=vault_url, credential=DefaultAzureCredential())
    return client.get_secret(name).value
